import { useState, useRef, useEffect } from 'react';
import ReactDOM from 'react-dom';
import { useLocation, useNavigate } from 'react-router-dom';
import { usePermission } from '@/core/rbac/usePermission';
import { getKhataBooks, switchKhataBook, getSelectedKhataBook, UserBasedAllMember } from '@/features/services/khataBookService';
import dashboardIcon from '../assets/dashboard.png';
import '../styles/Sidebar.css';

interface NavItem {
	title: string;
	path: string;
	icon: string;
	module?: string;
	modules?: string[];
	permission?: string;
	children?: NavItem[];
}

const navItems: NavItem[] = [
	{ title: 'DASHBOARD', path: '/dashboard', icon: '📊' },
	{
		title: 'PARTIES',
		path: '/parties',
		icon: '👥',
		children: [
			{ title: 'Customer', path: '/parties/customers', icon: '', module: 'customer' },
			{ title: 'Suppliers', path: '/parties/suppliers', icon: '', module: 'supplier' },
			// { title: 'Cash In Hand', path: '/parties/cash-bank/cash', icon: '' },
			// { title: 'Bank Deposit', path: '/parties/cash-bank/bank', icon: '' },
		],
	},
	{
		title: 'Inventory Management',
		path: '/inventory',
		icon: '📦',
		children: [
			{ title: 'Inventory', path: '/inventory/items', icon: '📦' },
			{ title: 'Sales', path: '/bills/sales', icon: '💰' },
			{ title: 'Purchase', path: '/bills/purchase', icon: '🛒' },
		],
	},
	{
		title: 'OTHERS',
		path: '/others',
		icon: '📦',
		children: [
			{ title: 'Staff MGMT', path: '/staff', icon: '👨‍💼', modules: ['staffManagement', 'staffAttendance'] },
			{ title: 'Rental Items', path: '/rental-items', icon: '📦', module: 'rental' },
			// { title: 'Note', path: '/others/note', icon: '📝' },
			{ title: 'Loan MGMT', path: '/others/loan', icon: '🏦', module: 'loan' },
		],
	},
	// {
	// 	title: 'REPORTS',
	// 	path: '/reports',
	// 	icon: '📊',
	// 	children: [
	// 		{ title: 'Sales Report', path: '/reports/sales', icon: '💰' },
	// 		{ title: 'Purchase Report', path: '/reports/purchase', icon: '🛒' },
	// 		{ title: 'Total Sale Report', path: '/reports/total-sale', icon: '📈' },
	// 	],
	// },
	// {
	// 	title: 'SYSTEM',
	// 	path: '/system',
	// 	icon: '⚙',
	// 	children: [
	// 		{ title: 'Reminder', path: '/system/reminder', icon: '⏰' },
	// 		{ title: 'Import Data', path: '/system/import', icon: '📥' },
	// 		{ title: 'Notis', path: '/system/notis', icon: '🔔' },
	// 	],
	// },
	{
		title: 'SETTINGS',
		path: '/settings',
		icon: '⚙️',
		children: [
			// { title: 'API', path: '/settings/api', icon: '💬' },
			{ title: 'Organization Management', path: '/organization', icon: '🌐', module: 'organization'},
			{ title: 'User Management', path:'/user-management', icon: '👤', module: 'user'},
			// { title: 'Backup', path: '/settings/backup', icon: '💾' },
			// { title: 'Recycle Bin', path: '/settings/recycle-bin', icon: '🗑️' },
			{ title: 'Role & Permission', path: '/role', icon: '🔒', module: 'roleAndPermissions' },
			{ title: 'App Setting', path: '/app-settings', icon: '⚙️', module: 'appSettings' },
			// { title: 'Bills & Print Selling', path: '/bills-and-print-selling', icon: '📄' },
			{ title: 'Business Setting', path: '/settings/business', icon: '🏢' },
			{ title: 'Dashboard Setting', path: '/settings/dashboard', icon: '📊' },
		],
	},
];

export const Sidebar = () => {
	const location = useLocation();
	const navigate = useNavigate();
	const { hasModule, hasPermission } = usePermission();

	const [isMobileOpen, setIsMobileOpen] = useState(false);
	const [isPopupOpen, setIsPopupOpen] = useState(false);
	const popupRef = useRef<HTMLDivElement>(null);
	const sidebarContainerRef = useRef<HTMLDivElement>(null);

	useEffect(() => {
		const handleToggle = () => setIsMobileOpen((prev) => !prev);
		const handleClose = () => setIsMobileOpen(false);

		window.addEventListener('toggle-sidebar', handleToggle);
		window.addEventListener('close-sidebar', handleClose);

		return () => {
			window.removeEventListener('toggle-sidebar', handleToggle);
			window.removeEventListener('close-sidebar', handleClose);
		};
	}, []);

	useEffect(() => {
		setIsMobileOpen(false);
	}, [location.pathname]);

	const [expandedItems, setExpandedItems] = useState<Record<string, boolean>>(() => {
		const saved = localStorage.getItem('sidebar_expanded_items');
		return saved ? JSON.parse(saved) : { '/parties': true };
	});

	const [khataBooks, setKhataBooks] = useState<UserBasedAllMember[]>([]);

	const [currentKhataBook, setCurrentKhataBook] = useState<UserBasedAllMember | null>(() => {
		const cachedId = localStorage.getItem('selectedKhataBookId');
		const cachedName = localStorage.getItem('companyName');
		if (cachedName) {
			return {
				id: cachedId ? Number(cachedId) : 0,
				organizationName: cachedName,
			} as UserBasedAllMember;
		}
		return null;
	});

	const [loading, setLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);

	// Guaranteed fallback display name chain
	const displayCompanyName =
		currentKhataBook?.organizationName ||
		(typeof window !== 'undefined' && localStorage.getItem('companyName')) ||
		'Select KhataBook';

	useEffect(() => {
		const savedScroll = sessionStorage.getItem('sidebar_scroll_position');
		if (sidebarContainerRef.current && savedScroll !== null) {
			sidebarContainerRef.current.scrollTop = Number(savedScroll);
		}
	}, []);

	const handleSidebarScroll = () => {
		if (sidebarContainerRef.current) {
			sessionStorage.setItem('sidebar_scroll_position', sidebarContainerRef.current.scrollTop.toString());
		}
	};

	useEffect(() => {
		localStorage.setItem('sidebar_expanded_items', JSON.stringify(expandedItems));
	}, [expandedItems]);

	const findParentPaths = (items: NavItem[], currentPath: string): string[] => {
		const parentPaths: string[] = [];
		const findParents = (items: NavItem[], path: string): boolean => {
			for (const item of items) {
				if (item.children) {
					if (
						item.children.some(
							(child) => child.path === path || (child.children && findParents([child], path))
						)
					) {
						parentPaths.push(item.path);
						return true;
					}
				}
			}
			return false;
		};
		findParents(items, currentPath);
		return parentPaths;
	};

	useEffect(() => {
		const parentPaths = findParentPaths(navItems, location.pathname);
		setExpandedItems((prev) => {
			const newExpanded = { ...prev };
			parentPaths.forEach((path) => {
				newExpanded[path] = true;
			});
			newExpanded['/parties'] = true;
			return newExpanded;
		});
	}, [location.pathname]);

	useEffect(() => {
		const handleClickOutside = (event: MouseEvent) => {
			if (popupRef.current && !popupRef.current.contains(event.target as Node)) {
				setIsPopupOpen(false);
			}
		};
		document.addEventListener('mousedown', handleClickOutside);
		return () => document.removeEventListener('mousedown', handleClickOutside);
	}, []);

	useEffect(() => {
		let isMounted = true;
		const fetchKhataBooks = async () => {
			if (isPopupOpen) {
				setLoading(true);
				setError(null);
				try {
					const data = await getKhataBooks();
					if (isMounted) setKhataBooks(data);
				} catch (err) {
					if (isMounted) setError('Failed to load KhataBooks');
					console.error(err);
				} finally {
					if (isMounted) setLoading(false);
				}
			}
		};

		fetchKhataBooks().catch((err) => console.error('Error fetching KhataBooks:', err));
		return () => {
			isMounted = false;
		};
	}, [isPopupOpen]);
	useEffect(() => {
		let isMounted = true;

		const fetchCurrentKhataBook = async () => {
			try {
				const selectedKhataBook: UserBasedAllMember = await getSelectedKhataBook();
				console.log("Selected KhataBook API Payload:", selectedKhataBook);

				if (selectedKhataBook && isMounted) {
					const orgName = selectedKhataBook.organizationName;

					if (orgName) {
						const formattedBook = {
							...selectedKhataBook,
							organizationName: orgName
						};
						setCurrentKhataBook(formattedBook);
						console.log("Organization Name:", orgName);
						localStorage.setItem('companyName', orgName);
						localStorage.setItem('selectedKhataBookId', selectedKhataBook.id.toString());
					}
				}
			} catch (err) {
				console.error('Failed to fetch current KhataBook:', err);
			}
		};

		fetchCurrentKhataBook();

		return () => {
			isMounted = false;
		};
	}, []);

	const isActive = (path: string, item: NavItem) => {
		if (path === '/') return false;
		if (path === '/parties/suppliers' && location.pathname.startsWith('/parties/supplier')) {
			return true;
		}
		const isPathActive = location.pathname.startsWith(path);
		if (item.children) {
			return item.children.some((child) => {
				if (child.children) {
					return child.children.some(
						(nestedChild) =>
							location.pathname === nestedChild.path || location.pathname.startsWith(nestedChild.path)
					);
				}
				const childAliasActive =
					child.path === '/parties/suppliers' && location.pathname.startsWith('/parties/supplier');
				return childAliasActive || location.pathname === child.path || location.pathname.startsWith(child.path);
			});
		}
		return isPathActive;
	};

	const toggleItem = (path: string) => {
		if (path === '/parties') return;
		setExpandedItems((prev) => ({
			...prev,
			[path]: !prev[path],
		}));
	};

	const filterAuthorizedNavItems = (items: NavItem[]): NavItem[] => {
		return items
			.filter((item) => {
				if (item.modules && !item.modules.some((m) => hasModule(m))) {
					return false;
				}
				if (item.module && !hasModule(item.module)) {
					return false;
				}
				if (item.permission && !hasPermission(item.permission)) {
					return false;
				}
				return true;
			})
			.map((item) => {
				if (item.children) {
					return {
						...item,
						children: filterAuthorizedNavItems(item.children),
					};
				}
				return item;
			})
			.filter((item) => !item.children || item.children.length > 0);
	};

	const renderNavItems = (items: NavItem[], level = 0) => {
		return items.map((item) => {
			const hasChildren = !!item.children?.length;
			const isExpanded = expandedItems[item.path];
			const active = isActive(item.path, item);

			const hideIconForPartiesChildren = level > 0 && item.path.startsWith('/parties/');
			const showIcon = !hideIconForPartiesChildren;

			return (
				<li key={item.path} className={`${level > 0 ? 'nested-nav-item' : 'nav-item'} mb-2`}>
					<div
						onClick={() => (hasChildren ? toggleItem(item.path) : navigate(item.path))}
						className={`${level > 0 ? 'nested-nav-link' : 'nav-link'} ${
							active ? 'active' : ''
						} d-flex align-items-center py-2 px-3 rounded`}
						style={{ paddingLeft: `${0.75 + level * 0.5}rem` }}
					>
						{showIcon && (
							<span className={`${level > 0 ? 'nested-nav-icon' : 'nav-icon'} me-2`}>
                         {item.title === 'DASHBOARD' ? (
							 <img src={dashboardIcon} alt="Dashboard" style={{ width: '28px', height: '28px' }} />
						 ) : (
							 item.icon
						 )}
                      </span>
						)}
						<span className={`${level > 0 ? 'nested-nav-text' : 'nav-text'} flex-grow-1`}>
                      {item.title}
                   </span>
						{hasChildren && item.path !== '/parties' && (
							<span className="expand-icon ms-auto">{isExpanded ? '▾' : '▸'}</span>
						)}
					</div>

					{hasChildren && isExpanded && (
						<ul className="nested-nav-items list-unstyled ms-3 mt-2">
							{renderNavItems(item.children!, level + 1)}
						</ul>
					)}
				</li>
			);
		});
	};

	const handleAddKhataBook = () => {
		setIsPopupOpen(false);
		navigate('/add-khatabook');
	};

	const handleKhataBookClick = async (khataBook: UserBasedAllMember) => {
		try {
			await switchKhataBook(khataBook.id, khataBook.referenceMemberId);
			setCurrentKhataBook(khataBook);
			localStorage.setItem('companyName', khataBook.organizationName);
			localStorage.setItem('selectedKhataBookId', khataBook.id.toString());
			window.location.reload();
		} catch (error) {
			console.error('Error switching KhataBook:', error);
			alert('Failed to switch KhataBook. Please try again.');
		}
		setIsPopupOpen(false);
	};

	const authorizedNavItems = filterAuthorizedNavItems(navItems);

	return (
		<>
			{isMobileOpen && (
				<div
					className="sidebar-backdrop"
					onClick={() => setIsMobileOpen(false)}
					aria-label="Close sidebar overlay"
				/>
			)}
			<div
				className={`sidebar ${isMobileOpen ? 'open' : ''}`}
				ref={sidebarContainerRef}
				onScroll={handleSidebarScroll}
			>
				<div className="sidebar-mobile-header">
					<span className="sidebar-mobile-title">Menu</span>
					<button
						type="button"
						className="sidebar-mobile-close-btn"
						onClick={() => setIsMobileOpen(false)}
						aria-label="Close menu"
					>
						✕
					</button>
				</div>

				<div className="user-section" onClick={() => setIsPopupOpen(true)}>
					<div className="user-profile" style={{ display: 'flex', flexDirection: 'column' }}>
						<div
							className="avatar"
							style={{
								backgroundImage: 'linear-gradient(135deg, #3498db, #2980b9)',
								backgroundSize: 'cover',
								backgroundPosition: 'center',
								backgroundRepeat: 'no-repeat',
							}}
						>
							{'👤'}
						</div>
						<div className="user-info">
							<p className="user-role">
								{displayCompanyName}
							</p>
						</div>
					</div>
				</div>

				{isPopupOpen && ReactDOM.createPortal(
					<div 
						className="popup-container"
						onClick={(e) => {
							if (e.target === e.currentTarget) {
								setIsPopupOpen(false);
							}
						}}
					>
						<div className="popup-content" ref={popupRef}>
							<div className="popup-header">
								<h2 className="popup-title">
									<i className="bi bi-buildings-fill popup-title-icon" />
									KhataBooks
								</h2>
								<button 
									type="button"
									className="close-button" 
									onClick={() => setIsPopupOpen(false)}
									aria-label="Close popup"
									title="Close"
								>
									✕
								</button>
							</div>
							<div className="user-cards-container">
								{loading ? (
									<p className="loading-text">Loading KhataBooks...</p>
								) : error ? (
									<p className="error-text">{error}</p>
								) : khataBooks.length === 0 ? (
									<p className="loading-text">No KhataBooks found</p>
								) : (
									khataBooks.map((khataBook) => {
										const isSelected =
											(currentKhataBook && currentKhataBook.id === khataBook.id) ||
											displayCompanyName === khataBook.organizationName;
										return (
											<div
												key={khataBook.id}
												className={`user-card ${isSelected ? 'active-org-card' : ''}`}
												onClick={() => handleKhataBookClick(khataBook)}
												title={`Switch to ${khataBook.organizationName}`}
											>
												<div className="user-image">
													{'👤'}
												</div>
												<div className="user-details">
													<div className="company-title-wrap">
														<h3 className="company-name">{khataBook.organizationName}</h3>
														{isSelected && (
															<span className="active-org-badge">Current</span>
														)}
													</div>
													<p className="user-info-text">
														{khataBook.organizationContactNumber || 'No phone'}
													</p>
												</div>
											</div>
										);
									})
								)}
							</div>
							<button type="button" className="add-button" onClick={handleAddKhataBook}>
								<span>Add New KhataBook</span>
							</button>
						</div>
					</div>,
					document.body
				)}

				<div className="nav-section">
					<ul className="nav-items list-unstyled">{renderNavItems(authorizedNavItems)}</ul>
				</div>
			</div>
		</>
	);
};